/bin/zsh -lc "node - <<'NODE'
const fs=require('fs'), crypto=require('crypto');
const checks=[
 ['.planning/milestones/M003/reviews/evidence/cr313-design-entry-109/product-manifest.json','files'],
 ['.planning/milestones/M003/reviews/evidence/cr313-design-entry-109/before-manifest.json','files']
];
for (const [f,k] of checks) {
 const m=JSON.parse(fs.readFileSync(f)); let bad=[]; let n=0;
 for(const [p,want] of Object.entries(m[k])) {n++; let got; try {got=crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex')} catch(e){got='MISSING'}; if(got"'!==want) bad.push([p,want,got]);}
 console.log(`${f}: ${n-bad.length}/${n} match`);
 if(bad.length) console.log(JSON.stringify(bad,null,2));
}
const project=fs.readFileSync('"'.planning/agt/project.yaml','utf8');
const m=project.match(/source: (profiles\\/consumer-ai-web\\/PROFILE.yaml)\\n    sha256: ([0-9a-f]+)/);
const p='../agt-coding-v2/'+m[1];
const got=crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
console.log("'`profile ${p}: ${got===m[2]?'"'MATCH':'MISMATCH'} expected="'${m[2]} actual=${got}`);
